  "workshop.systems.total.other": "Подготовленных материалов: {count}",
  "workshop.systems.description": "Используйте только те инструменты, которые нужны вашей игре: заполнять все разделы до начала игры не требуется. Кузня миров, действующие лица, регион, фракции и лор показывают одни и те же записи с разных сторон, поэтому изменения сразу видны во всех разделах. Мастерская остаётся вашей, пока вы не перенесёте материалы в кампанию. Плагин собирает их в единый пакет мира, который можно установить на сервере и использовать в своей кампании.",
  "workshop.systems.footer": "Все материалы здесь доступны только вам. При создании кампании вы сможете импортировать нужные.",

