  "workshop.create.choice.outline.step.0.label": "Составить план мира по идее",
  "workshop.create.choice.outline.step.0.detail": "Опишите задумку парой предложений. Модель подготовит план с людьми, местами, фракциями и лором, а также предложит существ и предметы с отдельными счётчиками. Вы отметите, что создать; существа и предметы пройдут проверку в бестиарии и разделе домашних материалов.",
