  "workshop.contentImport.note.worldConflict.value": "{slice} «{label}»: значение поля «{field}» изменилось и в кампании, и в импортируемых данных. Сохранён вариант кампании.",
  "workshop.contentImport.note.worldConflict.linkChanged": "Связь «{from} — {label} → {to}» изменилась и в кампании, и в импортируемых данных. Сохранён вариант кампании.",
  "workshop.contentImport.note.worldConflict.linkRemoved": "Связь «{from} — {label} → {to}» удалена из импортируемых данных, но была изменена в кампании, поэтому сохранён вариант кампании.",
