  "workshop.world.panel.tableNote": "Мир этой кампании. Материалы, перенесённые из мастерской, становятся отдельной копией кампании: изменения здесь не затрагивают исходную мастерскую. Эту вкладку видит только тот, кто управляет ходом истории.",
  "workshop.world.panel.description": "Кузня миров от Smoebo встроена в мастерскую. Её записи — это те же действующие лица, места, фракции и лор, которые используются в игре.",
  "workshop.world.panel.import.title": "Добавить экспорт Кузни миров в этот мир",
  "workshop.world.panel.import.button": "Открыть файл Кузни миров",
  "workshop.world.panel.export.title": "Сохранить этот мир в формате Кузни миров",
  "workshop.world.panel.export.button": "Сохранить файл Кузни миров",
  "workshop.world.panel.export.checkFailed": "Не удалось проверить файл. Попробуйте ещё раз.",
  "workshop.world.panel.export.lossWarning": "Файл Кузни миров хранит сцены в виде последовательности и не может вместить все элементы этой раскадровки. Пока ничего не сохранено.",
  "workshop.world.panel.export.lossesLabel": "Что потеряет каждая карточка раскадровки",
  "workshop.world.panel.export.bundleNote": "Набор мастерской сохраняет приключение целиком: все карточки, стрелки, маршруты и выбранные для карточек материалы.",
  "workshop.world.panel.export.saveAnyway": "Всё равно сохранить файл",
  "workshop.world.panel.export.shareInstead": "Вместо этого поделиться набором",
  "workshop.world.panel.import.lossWarning": "Этот файл нельзя импортировать целиком. Пока ничего не перенесено.",
  "workshop.world.panel.import.lossesLabel": "Что потеряет каждая сцена при превращении в карточку раскадровки",
  "workshop.world.panel.import.bringAnyway": "Всё равно импортировать",
  "workshop.world.panel.cancel": "Отмена",
  "workshop.world.panel.capability.both": "Для плана мира, извлечения из заметок, вопросов, черновика и рисования нужен ИИ (текстовая модель и система генерации изображений), но на этом сервере они не настроены. Остальные инструменты работают и без них; изображения можно загружать вручную. Администратор может включить функции в разделах «Администрирование → Настройки текстовой модели» и «Администрирование → Генерация изображений».",
  "workshop.world.panel.capability.text": "Для плана мира, извлечения из заметок, вопросов и черновика нужна текстовая модель, но на этом сервере она не настроена. Остальные инструменты работают и без неё. Администратор может включить её в разделе «Администрирование → Настройки текстовой модели».",
  "workshop.world.panel.capability.images": "Для рисования нужна система генерации изображений, но на этом сервере она не настроена. Изображения можно загружать вручную. Администратор может включить её в разделе «Администрирование → Генерация изображений».",
  "workshop.world.panel.loading": "Загрузка мира",
  "workshop.world.forge.intro": "Вставьте заметки о мире. Кузня найдёт людей, места и предметы, которые стоит оформить в записи, а также связи между ними. Вы сами выбираете, что сохранить.",
  "workshop.world.forge.notesPlaceholder": "Смотритель Иво охраняет морскую стену Гуллхейвена. Никто не знает, что он продал коды шлюзов контрабандистам из «Серого фонаря»...",
