  "workshop.world.import.loss.scenesOverCapacity": "Не помещается {count} сцен: сюжетная доска вмещает не более {limit} карточек.",
  "workshop.world.import.note.storyboardScenes": "Сцены каждой истории переносятся на доску последовательностью карточек «Событие». Исходные названия историй не сохраняются; при повторном импорте уже перенесённые карточки обновляются, а не дублируются.",
  "workshop.world.import.note.secretsKnowledge": "Новые для этого мира тайны считаются неизвестными игрокам. При повторном импорте сохраняется то, что партия уже успела узнать, а список тех, кто знает каждую тайну внутри мира, переносится без изменений.",
