  "workshop.world.import.note.regionRootWithPicture": "Карта «{name}» теперь служит картой Региона и задаёт её изображение; отмеченные на ней места размещены на карте Региона.",
  "workshop.world.import.note.regionRootWithoutPicture": "Карта «{name}» теперь служит основной картой Региона; отмеченные на ней места размещены на карте Региона.",
  "workshop.world.import.note.regionPinsKept": "Места, уже находившиеся на карте «{map}» ({count}), сохранили свои позиции в Регионе. Разместите их через Атлас, чтобы совместить карты.",
  "workshop.world.import.note.regionAlreadyHasPicture": "У карты Региона уже есть собственное изображение, поэтому новые места с карты «{map}» не были размещены. Чтобы перенести их, используйте эту карту как изображение-фон Региона.",
  "workshop.world.export.note.storyboardOrder": "При экспорте карточки сюжетной линии преобразуются в последовательность сцен. Их расположение на доске не сохранится, а карточки из других ветвей вернутся как элементы одной цепочки.",
